W = 6
P = "Verbeterproject"
PR = "Presentatie"

# ---------- MC: overdracht en lessons learned ----------
mc("pp6-m01", W, P, "Wanneer is het project volgens de les van week 6 pas echt af?",
   ["Als het adviesrapport is ingeleverd",
    "Als de proceseigenaar het kan overnemen",
    "Als de pilot geslaagd is",
    "Als de eindpresentatie is gegeven"], 1,
   "Het project is pas af als de proceseigenaar het kan overnemen, niet als jullie adviesrapport klaar is.")
mc("pp6-m02", W, P, "Welk moment noemt de les het kwetsbaarste moment van het verbetertraject?",
   ["De start van de pilot op één afdeling",
        "Het moment dat het studentteam vertrekt",
        "De keuze met de PUGH-matrix in week 2",
        "De nulmeting aan het begin van het project"], 1,
   "Zodra de aandacht verslapt, sluipt variatie (mura) terug. Daarom is het einde van het traject net zo cruciaal als de start.")
mc("pp6-m03", W, P, "Wanneer hoort de overdracht volgens de notities idealiter in de projectplanning te staan?",
   ["Vanaf de start van het project", "Pas na de eindpresentatie", "Zodra de pilot is afgerond", "Als de opdrachtgever erom vraagt"], 0,
   "Overdracht is een geplande activiteit, geen formaliteit achteraf. Idealiter staat ze vanaf de start in de planning.")
mc("pp6-m04", W, P, "Welke instrumenten helpen volgens de notities om eigenaarschap al vóór de overdracht op te bouwen?",
   ["Een FMEA en een PUGH-matrix samen met de eigenaar",
        "Visual control met KPI-borden en een dagstart",
        "Een RACI-matrix en een stakeholdersanalyse",
        "Een enquête onder klanten over het nieuwe proces"], 1,
   "Eigenaarschap ontstaat niet vanzelf op het overdrachtsmoment. Je bouwt het op door de eigenaar nu al te betrekken, bijvoorbeeld met KPI-borden en een dagstart.")
mc("pp6-m05", W, P, "Maak de uitspraak uit de notities af: 'Een standaard die van niemand is, ...'",
   ["... wordt vanzelf beter.", "... verstoft.", "... hoort in het archief.", "... is een quick win."], 1,
   "Zonder eigenaar wordt de standaard niet gevolgd en niet bijgewerkt.")
mc("pp6-m06", W, P, "Welke van deze vier hoort níét in het overdrachtsdossier?",
   ["De werkstandaard (SOP of EPL)",
    "Het borgingsplan met KPI's, normen en evaluatieritme",
    "De individuele portfolio's van de teamleden",
    "De losse eindjes en de lessons learned"], 2,
   "Het dossier bevat: werkstandaard, borgingsplan, eigenaarschap, projectdocumentatie (analyse, current en future state) en losse eindjes plus lessons learned. Je portfolio is voor je eigen beoordeling.")
mc("pp6-m07", W, P, "Wat is de vuistregel voor de volledigheid van het overdrachtsdossier?",
   ["Zo kort mogelijk, hooguit twee pagina's",
    "Zo compleet dat iemand zónder jullie ermee verder kan",
    "Precies even lang als het adviesrapport",
    "Alleen wat de opdrachtgever expliciet heeft gevraagd"], 1,
   "Het dossier moet de verbetering onafhankelijk maken van het studentteam.")
mc("pp6-m08", W, P, "Welk punt staat níét op de agenda van een Tollgate-gesprek?",
   ["Een korte samenvatting met een storyboard",
    "Toetsen aan de vooraf afgesproken succescriteria",
    "Nieuwe oplossingen brainstormen voor het probleem",
    "De verandering formeel overdragen"], 2,
   "Op de agenda: storyboard, wat ging goed en fout, toetsen aan de succescriteria en formeel overdragen. Oplossingen bedenk je veel eerder in het traject.")
mc("pp6-m09", W, P, "Wat is de gouden regel bij de overdracht?",
   ["Draag pas over als de proceseigenaar het echt kan dragen; daarna pas ontbind je het team",
    "Draag over op de laatste werkdag, ook als niet alles af is",
    "Draag over aan de docent, die het doorgeeft aan de organisatie",
    "Draag over zodra het adviesrapport een voldoende heeft gekregen"], 0,
   "Je ontbindt het team pas als de eigenaar de verbetering echt kan dragen.")
mc("pp6-m10", W, P, "Welke stap uit het zesstappenplan komt direct na 'draag over, formeel, aan de proceseigenaar'?",
   ["Toets succes aan de vooraf gestelde criteria", "Veranker en archiveer de verandering", "Documenteer alles in het dossier", "Projectafsluiting met belanghebbenden"], 1,
   "1 Documenteer, 2 Projectafsluiting, 3 Toets succes, 4 Draag over, 5 Veranker en archiveer, 6 Borg de lessen.")
mc("pp6-m11", W, P, "'Beslissingen gelden alleen voor de toekomst.' Wat betekent dat voor lessons learned?",
   ["Lessons learned hebben na het afronden van het project geen echte waarde meer",
        "Het rendement zit niet in je eigen project, maar bij het volgende team en de opdrachtgever",
        "Je mag lessons learned pas opschrijven als het besluit een jaar in werking is",
        "Alleen de opdrachtgever mag besluiten welke lessen voor de toekomst gelden"], 1,
   "Je kunt je eigen project niet meer veranderen. De waarde is dat anderen niet in dezelfde valkuil trappen.")
mc("pp6-m12", W, P, "Wat gebeurt er in Lean met een geleerde les?",
   ["Hij wordt opgenomen in de bijgewerkte standaard", "Hij gaat naar het archief van de docent", "Hij wordt alleen in de portfolio opgenomen", "Hij wordt besproken en daarna losgelaten"], 0,
   "Observeren, verbeteren, vastleggen: zo leert niet alleen het individu, maar de hele organisatie.")
mc("pp6-m13", W, P, "Welke aanname bleek in het praktijkvoorbeeld van de vergaderzalen niet te kloppen?",
   ["Dat het zaalteam de checklist zou omarmen", "Dat iedereen digitaal reserveert", "Dat de keuken de deadline zou halen", "Dat de coördinator proceseigenaar wilde worden"], 1,
   "Een deel van de medewerkers bleef bellen. De checklist werd juist direct omarmd.")
mc("pp6-m14", W, P, "In welke kolom van het lessons-learned-format zit volgens de notities de echte waarde?",
   ["Wat ging goed of kon beter", "Concrete les: wat doe je voortaan", "Voor wie", "Best practice ja of nee"], 1,
   "Een goede les is concreet en gedragen, geen algemene dooddoener.")
mc("pp6-m15", W, P, "Wat bedoelt de les met een 'best practice'?",
   ["Het hoogste cijfer dat een team in de klas heeft gehaald",
        "Een sterk inzicht dat herbruikbaar is in vergelijkbare projecten",
        "Een les die alleen voor het eigen projectteam geldt",
        "De oplossing die het hoogst scoorde in de PUGH-matrix"], 1,
   "Je tilt de sterkste inzichten uit de lessons learned naar best practice, zodat andere projecten ze kunnen gebruiken.")

# ---------- MC: training 4 ----------
mc("pp6-m16", W, PR, "Bij de generale repetitie duurt jullie presentatie 42 minuten. Wat doe je?",
   ["Niets, want de vragenronde mag dan gewoon korter",
        "Inkorten tot 30 minuten, want er volgen 15 minuten vragen",
        "De vragenronde schrappen zodat alles erin past",
        "Sneller praten zodat alle slides aan bod komen"], 1,
   "Het echte moment is 30 minuten presenteren plus 15 minuten vragen. Spreek af wie de tijd bijhoudt.")
mc("pp6-m17", W, PR, "Wat doe je volgens de training met de mondelinge feedback op je generale repetitie?",
   ["Onthouden en meteen in de eindpresentatie verwerken",
        "Dezelfde dag in je logboek, met de naam van de gever",
        "Laten ondertekenen door de docent voor je portfolio",
        "Alleen opschrijven als de feedback kritisch was"], 1,
   "Peerfeedback telt als extra feedbackbron voor je portfolio.")
mc("pp6-m18", W, PR, "Een groep begint de generale repetitie met hun advies en legt daarna pas uit wat het probleem is. Welke opbouw raadt de training aan voor de kern?",
   ["Advies, Oorzaak, Risico, Probleem", "Probleem, Risico, Oorzaak, Advies", "Oorzaak, Probleem, Advies, Risico", "Risico, Advies, Probleem, Oorzaak"], 1,
   "PROA: Probleem (Define, Measure), Risico of omvang (Measure), Oorzaak (Analyze), Advies (Generate, Improve, Control).")

# ---------- open ----------
op("pp6-o1", W, P, "Leg uit waarom overdracht een geplande activiteit is en geen formaliteit achteraf. Gebruik het begrip 'Lean Back'.",
   "Het vertrek van het studentteam is het kwetsbaarste moment: zodra de aandacht verslapt, sluipt variatie terug en binnen enkele maanden is het oude patroon terug. Eigenaarschap ontstaat niet vanzelf op het overdrachtsmoment; je bouwt het op door de eigenaar vanaf het begin te betrekken. Daarom staat overdracht idealiter vanaf de start in de planning. Lean Back: het studentteam stuurt en faciliteert, de proceseigenaar heeft het mandaat en is verantwoordelijk voor de uitvoering; de organisatie blijft eigenaar van haar eigen proces.",
   ["Kwetsbaar moment of terugval uitgelegd", "Eigenaarschap moet vooraf opgebouwd worden", "Lean Back juist uitgelegd"])
op("pp6-o2", W, P, "Een team heeft de schoonmaakrondes in een kantoorgebouw verbeterd. Stel het overdrachtsdossier samen: welke vijf onderdelen horen erin en wat stop je er bij dit project in?",
   "1 Werkstandaard: SOP of EPL van de nieuwe schoonmaakronde. 2 Borgingsplan: KPI's (bijvoorbeeld percentage ruimtes dat bij controle schoon is, norm en ingrijpgrens) en evaluatieritme. 3 Eigenaarschap: bijvoorbeeld de objectleider schoonmaak als proceseigenaar, met afspraken over mandaat. 4 Projectdocumentatie: analyse, current state en future state van de rondes. 5 Losse eindjes: openstaande acties (bijvoorbeeld nieuwe trolleys bestellen) plus de lessons learned.",
   ["Minstens drie onderdelen juist", "Alle vijf onderdelen juist", "Concreet ingevuld voor de schoonmaakrondes"])
op("pp6-o3", W, P, "Noem de zes stappen van project naar overdracht. Wanneer geldt het project als afgerond?",
   "1 Documenteer alles in het dossier. 2 Projectafsluiting met belanghebbenden. 3 Toets het succes aan de vooraf gestelde criteria. 4 Draag formeel over aan de proceseigenaar. 5 Veranker en archiveer de verandering. 6 Borg de lessen (lessons learned). Het project geldt pas als afgerond wanneer álle stappen zijn voltooid.",
   ["Minstens vier stappen juist", "Alle zes in de juiste volgorde", "Pas afgerond na alle stappen"])
op("pp6-o4", W, P, "Een team schrijft als lesson learned: 'De communicatie had beter gekund.' Waarom is dit geen goede les? Maak er een goede les van en zeg voor wie die waardevol is.",
   "Het is een algemene dooddoener: niet concreet, niet gedragen en je weet niet wat je voortaan anders doet. Een goede les zegt wat je voortaan doet, bijvoorbeeld: 'Plan vanaf week 1 een wekelijkse update van tien minuten met de receptie en de technische dienst, want zij hoorden pas in week 5 van de wijziging.' Waardevol voor het volgende team (vermijdt de valkuil), de opdrachtgever (verbetert verder) en jezelf (transfer naar stage). Eventueel tillen naar best practice.",
   ["Uitleg waarom het een dooddoener is", "Concrete les: wat doe je voortaan", "Voor wie waardevol"])
op("pp6-o5", W, P, "Wat is een Tollgate? Wie zijn erbij en wat staat er op de agenda?",
   "Een Tollgate is het formele overdrachtsgesprek of de projectafsluiting, het scharnierpunt waarop de verantwoordelijkheid overgaat naar de proceseigenaar. Erbij: de belanghebbenden, zoals opdrachtgever, proceseigenaar (bijvoorbeeld facilitair coördinator) en betrokken teams zoals technische dienst of zaalteam. Agenda: korte samenvatting (storyboard), wat ging goed en fout, toetsen aan de vooraf afgesproken succescriteria, de verandering formeel overdragen.",
   ["Tollgate juist omschreven", "Juiste deelnemers", "Minstens drie agendapunten"])
op("pp6-o6", W, PR, "Bij de generale repetitie krijg je de feedback: 'Ik weet niet wat jullie van de opdrachtgever willen.' Welke vragen over de ontvanger had je vooraf moeten beantwoorden, en hoe pas je het slot van je presentatie aan?",
   "Vragen over de ontvanger: wat weet de ontvanger al, wat zijn de belangen, wat heeft de ontvanger nodig (wie beslist, focus op financiën of argumenten) en, nieuw in training 4, wat wil de ontvanger? Denk vanuit de beslisser: wat heeft die nodig om ja te zeggen? Aanpassing: eindig met een duidelijke vraag of beslissing die je van de opdrachtgever vraagt, bijvoorbeeld akkoord op de uitrol en het aanwijzen van een proceseigenaar, gekoppeld aan de opbrengst en het implementatieplan.",
   ["Minstens drie vragen over de ontvanger", "'Wat wil de ontvanger' genoemd", "Concreet slot met een vraag aan de beslisser"])

# ---------- casus ----------
cs("pp6-c1", W, P, "Nieuw sleutelbeheer bij woningcorporatie Waalwonen",
   "Bij woningcorporatie Waalwonen (fictief) heeft een studentteam het sleutelbeheer voor monteurs verbeterd: een sleutelkast met registratie en een vaste uitgifteprocedure. Het team wil volgende week overdragen. In het dossier staat als proceseigenaar 'de teamleider vastgoedonderhoud'. Bij navraag blijkt die nog nooit van het project gehoord te hebben. Het team stelt voor het dossier op de laatste dag te mailen en dan af te sluiten.",
   [("Wat gaat er mis met het eigenaarschap, en wat moet het team doen voordat het overdraagt?",
     "De beoogde eigenaar weet van niets; dat is volgens de notities een veelvoorkomend probleem. Eigenaarschap ontstaat niet op het overdrachtsmoment. Het team moet de teamleider nu betrekken: het project uitleggen, akkoord vragen, mandaat vastleggen, en de teamleider laten meekijken bij de KPI's, bijvoorbeeld via een weekstart met het KPI-bord. Pas als de teamleider het echt kan dragen, wordt er overgedragen.",
     ["Probleem benoemd: eigenaar weet het niet", "Concrete acties om eigenaarschap op te bouwen", "Gouden regel: pas overdragen als de eigenaar het kan dragen"]),
    ("Beoordeel het plan om het dossier te mailen en af te sluiten. Wat stel je voor in plaats daarvan?",
     "Mailen is geen actieve overdracht en geen formele afsluiting. Voorstel: een Tollgate-gesprek met de opdrachtgever, de teamleider vastgoedonderhoud en een vertegenwoordiger van de monteurs. Agenda: storyboard, wat ging goed en fout, toetsen aan de succescriteria, formeel overdragen. Daarna verankeren (procedures bijwerken), archiveren en lessons learned borgen.",
     ["Mailen afgewezen met reden", "Tollgate met juiste deelnemers en agenda", "Verankeren, archiveren of lessons learned genoemd"])])
cs("pp6-c2", W, P, "Lessons-learned-sessie na de verhuizing van een afdeling",
   "Een team begeleidde de verhuizing van een afdeling naar een flexplekkenconcept. Hun lessons learned: (1) 'Het ging over het algemeen goed.' (2) 'Planning was lastig.' (3) 'De IT-afdeling werd pas betrokken toen de werkplekken al waren ingericht, waardoor de dockingstations niet pasten.' (4) 'We gingen ervan uit dat iedereen thuis zou werken op vrijdag, maar 70% kwam toch.'",
   [("Welke lessen zijn bruikbaar en welke niet? Leg uit waarom.",
     "Les 1 en 2 zijn dooddoeners: niet concreet en je weet niet wat je voortaan anders doet. Les 3 is bruikbaar: concrete oorzaak en gevolg. Les 4 is een aanname die niet klopte, ook bruikbaar. Maar 3 en 4 zijn nog als probleem geformuleerd, niet als 'wat doe je voortaan'.",
     ["1 en 2 als dooddoener herkend", "3 en 4 als bruikbaar herkend met reden"]),
    ("Maak van les 3 en 4 een concrete les en geef aan of het een best practice is en voor wie die waardevol is.",
     "Les 3: 'Betrek IT vanaf de eerste ontwerpsessie bij de inrichting van werkplekken.' Best practice: ja, herbruikbaar bij elke inrichting. Waardevol voor het volgende team en de opdrachtgever. Les 4: 'Toets aannames over bezetting met een bezettingsmeting vóór het ontwerp, niet achteraf.' Best practice: ja. Waardevol voor de opdrachtgever (bij volgende afdelingen) en voor jezelf op stage.",
     ["Les 3 als concrete 'voortaan'-les", "Les 4 als concrete 'voortaan'-les", "Best practice en doelgroep benoemd"])])
cs("pp6-c3", W, P, "Overdracht van het nieuwe receptieproces bij Hotel Nijmeegse Poort",
   "Bij Hotel Nijmeegse Poort (fictief) verbeterde een team het inchecken: online voorregistratie en een vaste checklist aan de balie. De wachttijd daalde van 9 naar 4 minuten. De front office manager wordt proceseigenaar. Het team heeft twee weken over.",
   [("Plan de overdracht met het zesstappenplan. Wat doet het team concreet bij elke stap?",
     "1 Documenteren: dossier met checklist (werkstandaard), KPI wachttijd met norm, eigenaarschap, analyse en current/future state, losse eindjes. 2 Projectafsluiting: Tollgate met hotelmanager, front office manager en receptieteam. 3 Succes toetsen: wachttijd 4 minuten tegen het vooraf gestelde criterium. 4 Formeel overdragen aan de front office manager. 5 Verankeren in de werkinstructies van de receptie en archiveren. 6 Lessons learned vastleggen.",
     ["Minstens vier stappen concreet", "Alle zes stappen concreet in de juiste volgorde"]),
    ("Hoe zorgt het team dat het eigenaarschap van de front office manager al vóór de Tollgate groeit?",
     "Nu al betrekken: de manager de KPI laten bespreken in de dagstart of weekstart van de receptie, een visual control bord met de wachttijd bij de back office, samen de checklist bijstellen, en vragen beantwoorden zodat het geen verrassing is. 'Een standaard die van niemand is, verstoft.'",
     ["Concreet instrument zoals dagstart of KPI-bord", "Eigenaar actief betrekken vóór de overdracht"])])
